public class VolatileCounter {
    private volatile int count = 0;

    public void increment() {
        count++; // NOT atomic! Race condition here
    }

    public int getCount() {
        return count;
    }
}

// Problem: count++ is actually:
// 1. Read count
// 2. Increment
// 3. Write count
// Multiple threads can interleave these steps.

import java.util.concurrent.atomic.AtomicInteger;

public class AtomicCounter {
    private AtomicInteger count = new AtomicInteger(0);

    public void increment() {
        count.incrementAndGet(); // Atomic operation
    }

    public int getCount() {
        return count.get();
    }
}

import java.util.concurrent.atomic.AtomicInteger;

public class AtomicExample {
    private AtomicInteger value = new AtomicInteger(0);

    public boolean updateIfExpected(int expected, int newValue) {
        // Atomically sets to newValue if current value == expected
        return value.compareAndSet(expected, newValue);
    }
}

